var zone = new ArcMorphSelect
{
    Label = "时区",
    Width = 200,
    Searchable = true,
    SearchPlaceholder = "搜索城市",
    Items = new List<ArcMorphSelectItem>
    {
        new ArcMorphSelectGroup(
            "Europe",
            new ArcMorphSelectOption("europe/london", "London", "UTC+0"),
            new ArcMorphSelectOption("europe/zurich", "Zurich", "UTC+1")),
        new ArcMorphSelectGroup(
            "Americas",
            new ArcMorphSelectOption("america/new_york", "New York", "UTC−5"))
    }
};

zone.ValueChanged += (_, e) => Save(e.Value);
